import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public abstract class OwnerMapper {

    /** Household size at or above which an owner reaches the 'GOLD' tier. */
    private static final int GOLD_HOUSEHOLD_SIZE = 3;

    @Autowired
    protected OwnerRepository ownerRepository;

    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    public abstract OwnerDto toOwnerDto(Owner owner);

    /** City -> canonical region; anything not listed derives locality 'UNKNOWN'. */
    protected static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /**
     * The owner's locality, derived from the city using a fixed city-to-region table
     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or 'UNKNOWN' when the city is not
     * in the table.
     */
    protected String toLocality(Owner owner) {
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * The owner's membership tier: 'GOLD' when the owner's household (owners sharing the
     * same householdId) has 3 or more members; otherwise 'SILVER' when namesakeCount is 0
     * and an email is present, else 'BRONZE'.
     */
    protected OwnerDto.MembershipTierEnum toMembershipTier(Owner owner) {
        if (isGoldHousehold(owner)) {
            return OwnerDto.MembershipTierEnum.GOLD;
        }
        Integer namesakeCount = owner.getNamesakeCount();
        String email = owner.getEmail();
        boolean hasEmail = email != null && !email.isBlank();
        return (namesakeCount != null && namesakeCount == 0 && hasEmail)
                ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
    }

    /** Whether the owner's household has enough members to reach the 'GOLD' tier. */
    private boolean isGoldHousehold(Owner owner) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return false;
        }
        long members = ownerRepository.findAll().stream()
                .filter(existing -> householdId.equals(existing.getHouseholdId()))
                .count();
        return members >= GOLD_HOUSEHOLD_SIZE;
    }

    /** The owner's name formatted as 'LastName, FirstName'. */
    protected String toDisplayName(Owner owner) {
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
    protected String toInitials(Owner owner) {
        return owner.getFirstName().substring(0, 1).toUpperCase()
                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
    }

    public abstract Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
